        cmpa    #$62
        bcc     LAC5A
        ldab    #$01
        cmpa    #$3A
        bcc     LAC51
        incb
        cmpa    #$12
        bcc     LAC51
        incb
LAC51:
        ldaa    <L0075
        adda    #$01
        anda    #$03
        cba
        bcs     LAC6B
LAC5A:
