        bls     LAE0C
        ldaa    <ChargeTemp
        cmpa    >KNAIAT_MinChargeTempForAverageKnockVoltCalc ; KNAIAT (MinChargeTempForAverageKnockVoltCalc)
        bcc     LAE0C
        brset   <BitFlasg71,#$02,LAE0C
        ldaa    <KeyOnOrEngineRunningTime
        cmpa    >KNAERT_MinEngRunTImeForAverageKnockVoltCalc ; KNAERT (MinEngRunTImeForAverageKnockVoltCalc)
        bls     LAE0C
        ldaa    <Counter_KnockVoltsAvg
        bne     LAE0C
        ldaa    <TpsVolts
        tab
        suba    >L0191
        bpl     LADB8
        nega
LADB8:
        cmpa    >KNATPS_MinThrotPosForAverageKnockVoltCalc ; KNATPS (MinThrotPosForAverageKnockVoltCalc)
        bcc     LAE0C
        subb    >L0193
        bpl     LADC3
        negb
LADC3:
        cmpb    >KNATPS_MinThrotPosForAverageKnockVoltCalc ; KNATPS (MinThrotPosForAverageKnockVoltCalc)
        bcc     LAE0C
        brclr   <b58_IPL1,#$A0,LADCE
LADCC:
        bra     LAE0C

LADCE:
        bset    <IPL1,#$04
        ldaa    >KNADFT_DefaultKnockVoltsAverage     ; KNADFT (DefaultKnockVoltsAverage)
        bne     LADDB
        ldaa    <KnockVolts
        clrb
        bra     LADF2

LADDB:
        ldy     <AverageKnockVolts
        jsr     >ScaleYbyA                           ; D = Y x A / 256 (unsigned fractional multiply).
        pshy
        ldaa    <KnockVolts
        ldab    >KNADFT_DefaultKnockVoltsAverage     ; KNADFT (DefaultKnockVoltsAverage)
        mul
        tsy
        subd    $00,y
        puly
        addd    <AverageKnockVolts
LADF2:
        std     <AverageKnockVolts
        cmpa    >KNAMAX_MaxAverageKnockVolts         ; KNAMAX (MaxAverageKnockVolts)
        bls     LADFF
        ldaa    >KNAMAX_MaxAverageKnockVolts         ; KNAMAX (MaxAverageKnockVolts)
        clrb
        bra     LAE08

LADFF:
        cmpa    >KNAMIN_MinAverageKnockVolts         ; KNAMIN (MinAverageKnockVolts)
        bcc     LAE08
        ldaa    >KNAMIN_MinAverageKnockVolts         ; KNAMIN (MinAverageKnockVolts)
        clrb
LAE08:
        std     <AverageKnockVolts
        bra     LAE0F

LAE0C:
        bclr    <IPL1,#$04
LAE0F:
        rts


